<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">IP 查询</text><text class="nav-icon" @click="query">✅</text></view></view><view class="content"><view class="ip-card"><text class="ip-label">您的 IP</text><text class="ip-value">{{ ip }}</text></view><view class="ip-details" v-if="info"><view class="ip-row"><text class="ip-k">地区</text><text class="ip-v">{{ info.city }}</text></view><view class="ip-row"><text class="ip-k">运营商</text><text class="ip-v">{{ info.isp }}</text></view></view><view class="ip-btn" @click="query"><text>查询</text></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const ip = ref("..."); const info = ref(null)
